"""data/loader.py — Chargement unique et mis en cache de tous les fichiers Excel."""import osimport pandas as pdimport streamlit as st_DATA_DIR = os.path.join(os.path.dirname(__file__))_DASH   = os.path.join(_DATA_DIR, "chrono24_dashboard.xlsx")_HEALTH = os.path.join(_DATA_DIR, "Chrono24_SellerHealth_PowerBI_Model.xlsx")# ══════════════════════════════════════════════════════════════# MODULE 1 — Flux Commerciaux# ══════════════════════════════════════════════════════════════@st.cache_data(show_spinner=False)def load_raw() -> pd.DataFrame:    df = pd.read_excel(_DASH, sheet_name="📊 Données Brutes")    df.columns = [c.strip() for c in df.columns]    df["Année"] = df["Année"].fillna(0).astype(int)    df["Domestique"] = df["Domestique"].astype(bool)    return df@st.cache_data(show_spinner=False)def load_flux_top20() -> pd.DataFrame:    df = pd.read_excel(_DASH, sheet_name="📈 Flux Commerciaux", skiprows=1)    df = df.dropna(subset=["Pays Acheteur"])    for c in ["Nb Transactions", "Note Globale", "Score Livraison", "Score Communication"]:        df[c] = pd.to_numeric(df[c], errors="coerce")    df["Part (%)"] = (        df["Part du total"].astype(str)        .str.replace("%", "", regex=False).str.strip()    )    df["Part (%)"] = pd.to_numeric(df["Part (%)"], errors="coerce")    df["Flux"] = df["Pays Acheteur"] + " → " + df["Pays Vendeur"]    return df.reset_index(drop=True)@st.cache_data(show_spinner=False)def load_geo() -> dict:    raw = pd.read_excel(_DASH, sheet_name="🌍 Géographie", header=None)    buyers = raw.iloc[2:12, :3].copy()    buyers.columns = ["Pays", "Nb achats", "Part (%)"]    buyers = buyers.dropna(subset=["Pays"])    buyers["Nb achats"] = pd.to_numeric(buyers["Nb achats"], errors="coerce")    buyers["Part (%)"]  = pd.to_numeric(        buyers["Part (%)"].astype(str).str.replace("%","").str.strip(), errors="coerce")    sellers = raw.iloc[2:12, 4:7].copy()    sellers.columns = ["Pays", "Nb ventes", "Part (%)"]    sellers = sellers.dropna(subset=["Pays"])    sellers["Nb ventes"] = pd.to_numeric(sellers["Nb ventes"], errors="coerce")    sellers["Part (%)"]  = pd.to_numeric(        sellers["Part (%)"].astype(str).str.replace("%","").str.strip(), errors="coerce")    bal_idx = raw[raw.iloc[:, 0] == "Pays"].index    bal_start = bal_idx[1] if len(bal_idx) > 1 else 16    bal = raw.iloc[bal_start:bal_start+20, :5].copy()    bal.columns = ["Pays", "Ventes", "Achats", "Balance", "Statut"]    bal = bal.dropna(subset=["Pays"])    for c in ["Ventes", "Achats", "Balance"]:        bal[c] = pd.to_numeric(bal[c], errors="coerce")    bal = bal.dropna(subset=["Balance"])    return {"buyers": buyers.reset_index(drop=True),            "sellers": sellers.reset_index(drop=True),            "balance": bal.reset_index(drop=True)}@st.cache_data(show_spinner=False)def load_satisfaction() -> dict:    raw = pd.read_excel(_DASH, sheet_name="⭐ Satisfaction", header=None)    dom_intl = raw.iloc[2:5, :5].copy()    dom_intl.columns = ["Type","Note Globale","Livraison","Description","Communication"]    dom_intl = dom_intl[dom_intl["Type"] != "Type"].dropna(subset=["Type"])    for c in ["Note Globale","Livraison","Description","Communication"]:        dom_intl[c] = pd.to_numeric(dom_intl[c], errors="coerce")    dom_intl["Type"] = dom_intl["Type"].str.replace("✈️ ","").str.replace("🏠 ","")    par_type = raw.iloc[7:11, :6].copy()    par_type.columns = ["Type","Nb transactions","Note Globale","Livraison","Description","Communication"]    par_type = par_type[par_type["Type"] != "Type"].dropna(subset=["Type"])    for c in ["Note Globale","Livraison","Description","Communication"]:        par_type[c] = pd.to_numeric(par_type[c], errors="coerce")    par_type["Nb transactions"] = pd.to_numeric(        par_type["Nb transactions"].astype(str).str.replace(",","").str.replace(" ",""),        errors="coerce")    top_sellers = raw.iloc[13:24, :6].copy()    top_sellers.columns = ["Pays vendeur","Nb transactions","Note Globale",                           "Livraison","Description","Communication"]    top_sellers = top_sellers[top_sellers["Pays vendeur"] != "Pays vendeur"].dropna(subset=["Pays vendeur"])    for c in ["Note Globale","Livraison","Description","Communication"]:        top_sellers[c] = pd.to_numeric(top_sellers[c], errors="coerce")    top_sellers["Pays vendeur"] = (        top_sellers["Pays vendeur"].astype(str)        .str.replace("🥇 ","").str.replace("🥈 ","").str.replace("🥉 ","").str.strip()    )    top_sellers["Nb transactions"] = pd.to_numeric(        top_sellers["Nb transactions"].astype(str).str.replace(",","").str.replace(" ",""),        errors="coerce")    return {"dom_intl": dom_intl.reset_index(drop=True),            "par_type": par_type.reset_index(drop=True),            "top_sellers": top_sellers.reset_index(drop=True)}@st.cache_data(show_spinner=False)def load_evolution() -> pd.DataFrame:    raw = pd.read_excel(_DASH, sheet_name="📅 Évolution", header=None)    df = raw.iloc[1:7, :6].copy()    df.columns = ["Année","Nb transactions","Note globale","Score livraison",                  "% International","Nb vendeurs"]    df = df.dropna(subset=["Année"])    df = df[df["Année"].astype(str).str.match(r'^\d{4}')]    df["Année"] = df["Année"].astype(str).str.extract(r'(\d{4})')[0].astype(int)    for c in ["Nb transactions","Note globale","Score livraison","Nb vendeurs"]:        df[c] = pd.to_numeric(            df[c].astype(str).str.replace(",","").str.replace(" ",""), errors="coerce")    df["% International"] = pd.to_numeric(        df["% International"].astype(str).str.replace("%","").str.strip(), errors="coerce")    return df.reset_index(drop=True)@st.cache_data(show_spinner=False)def load_brands() -> pd.DataFrame:    raw = pd.read_excel(_DASH, sheet_name="⌚ Marques", header=None)    df = raw.iloc[1:17, :5].copy()    df.columns = ["Marque","Nb transactions","Part (%)","Note globale","% Ventes intl."]    df = df.dropna(subset=["Marque"])    df["Marque"] = df["Marque"].astype(str).str.replace(" ...", "", regex=False).str.strip()    for c in ["Nb transactions","Note globale"]:        df[c] = pd.to_numeric(            df[c].astype(str).str.replace(",","").str.replace(" ",""), errors="coerce")    for c in ["Part (%)","% Ventes intl."]:        df[c] = pd.to_numeric(            df[c].astype(str).str.replace("%","").str.strip(), errors="coerce")    return df.dropna(subset=["Nb transactions"]).reset_index(drop=True)# ══════════════════════════════════════════════════════════════# MODULE 2 — Seller Health# ══════════════════════════════════════════════════════════════@st.cache_data(show_spinner=False)def load_health() -> pd.DataFrame:    df = pd.read_excel(_HEALTH, sheet_name="📋 HealthSnapshot", skiprows=1)    df.columns = [c.strip() for c in df.columns]    df = df.dropna(subset=["ID Vendeur"])    num_cols = ["ID Vendeur","Health Score","Membre Depuis","Probabilité Risque",                "Momentum Sentiment","Sentiment 6m","Volatilité 6m",                "% Avis Nég. 30j","Pente Sent. 3m","Note Snapshot",                "Note Livraison","Note Description","Note Communication",                "Nb Avis 3m","Nb Avis 6m","Nb Avis Total"]    for c in num_cols:        if c in df.columns:            df[c] = pd.to_numeric(df[c], errors="coerce")    return df.reset_index(drop=True)@st.cache_data(show_spinner=False)def load_country_health() -> pd.DataFrame:    df = pd.read_excel(_HEALTH, sheet_name="🌍 Analyse Pays", skiprows=1)    df.columns = [c.strip() for c in df.columns]    df = df.dropna(subset=["Pays"])    for c in ["Nb Vendeurs","Health Score Moy.","Note Snapshot Moy.",              "% Alertes HIGH","% Vendeurs OK","Nb HIGH Alerts"]:        df[c] = pd.to_numeric(df[c], errors="coerce")    return df.reset_index(drop=True)@st.cache_data(show_spinner=False)def load_diagnostics() -> pd.DataFrame:    df = pd.read_excel(_HEALTH, sheet_name="⚠️ Diagnostics Alertes", skiprows=1)    df.columns = [c.strip() for c in df.columns]    df = df.dropna(subset=["Vendeur"])    for c in ["Note","Health Score","Prob. Risque","Momentum","Sentiment 6m","Nb Avis"]:        if c in df.columns:            df[c] = pd.to_numeric(df[c], errors="coerce")    return df.reset_index(drop=True)